import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    static void bitAdd(long[] t, int i, long x) {
        int n = t.length - 1;
        for (; i <= n; i += i & -i) t[i] += x;
    }

    static long bitSum(long[] t, int i) {
        long s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }

    static int lowerBound(long[] a, long v) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = Long.parseLong(next());
        long[] b = new long[(int) n];
        for (int i = 0; i < b.length; i++) b[i] = Long.parseLong(next());

        long[] kb = new long[(int) n];
        for (int j = 0; j < n; j++) kb[j] = (b[j] << 17) | j;
        Arrays.sort(kb);
        int[] used = new int[(int) n];
        long[] t = new long[(int) n + 1];
        long inv = 0;
        for (int i = 0; i < n; i++) {
            int s = lowerBound(kb, a[i] << 17);
            int p = (int) (kb[s + used[s]] & 131071) + 1;
            used[s]++;
            inv += i - bitSum(t, p);
            bitAdd(t, p, 1);
        }
        System.out.println(inv);
    }
}
